422	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
423	    @Override
424	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
425	        HttpHeaders headers = new HttpHeaders();
426	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
427	        if (!isPostcodeValid(owner)) {
428	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
429	        }
430	        String telephone = toE164(owner.getTelephone());
431	        if (telephone == null || !hasValidNationalLength(telephone)) {
432	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
433	        }
434	        if (!normalizeEmail(owner)) {
435	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
436	        }
437	        String address = normalizeAddress(owner.getAddress());
438	        if (address.isEmpty()) {
439	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
440	        }
441	        owner.setAddress(address);
442	        owner.setTelephone(telephone);
443	        if (owner.getRegistrationDate() != null
444	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
445	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
446	        }
447	        java.time.LocalDate registrationDate = toBusinessDay(
448	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
449	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
450	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
451	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
452	        }
453	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
454	            return new ResponseEntity<>(HttpStatus.CONFLICT);
455	        }
456	        List<Owner> householdMembers = householdMembers(owner);
457	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
458	        if (sharesHousehold && !householdMembers.isEmpty()) {
459	            owner.setHouseholdId(householdMembers.stream()
460	                .map(Owner::getHouseholdId)
461	                .filter(id -> id != null && !id.isBlank())
462	                .findFirst()
463	                .orElseGet(() -> householdIdFor(owner)));
464	        }
465	        // Consolidated duplicate detection: the former separate telephone, email and household
466	        // checks are now all expressed through the single derived identityKey, so a new owner is
467	        // rejected only when its WHOLE identityKey equals an existing owner's. Because the telephone
468	        // is part of the key, two members of the same household with different telephones have
469	        // different identityKeys and are both allowed.
470	        String identityKey = owner.getIdentityKey();
471	        for (Owner existing : this.clinicService.findAllOwners()) {
472	            if (identityKey.equals(existing.getIdentityKey())) {
473	                return new ResponseEntity<>(HttpStatus.CONFLICT);
474	            }
475	        }
476	        if (owner.getHouseholdId() != null) {
477	            for (Owner member : householdMembers) {
478	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
479	                    member.setHouseholdId(owner.getHouseholdId());
480	                    this.clinicService.saveOwner(member);
481	                }
482	            }
483	        }
484	        Owner duplicateOf = possibleDuplicateOf(owner);
485	        owner.setPossibleDuplicate(duplicateOf != null);
486	        owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
487	        owner.setNamesakeCount(namesakeCount(owner));
488	        owner.setHouseholdSize(householdMembers.size() + 1);
489	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
490	        owner.setRegistrationDate(registrationDate);
491	        owner.setCustomerCode(customerCodeFor(owner));
492	        this.clinicService.saveOwner(owner);
493	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
494	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
495	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
496	        headers.setLocation(UriComponentsBuilder.newInstance()
497	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
498	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
499	    }
