501	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
502	    @Override
503	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
504	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
505	        if (currentOwner == null) {
506	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
507	        }
508	        currentOwner.setAddress(ownerFieldsDto.getAddress());
509	        currentOwner.setCity(ownerFieldsDto.getCity());
510	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
511	        currentOwner.setLastName(ownerFieldsDto.getLastName());
512	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
513	        currentOwner.setEmail(ownerFieldsDto.getEmail());
514	        if (!normalizeEmail(currentOwner)) {
515	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
516	        }
517	        this.clinicService.saveOwner(currentOwner);
518	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
519	    }
