535	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
536	        Owner owner = this.clinicService.findOwnerById(ownerId);
537	        if (owner == null) {
538	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
539	        }
540	        HttpHeaders headers = new HttpHeaders();
541	        Pet pet = petMapper.toPet(petFieldsDto);
542	        owner.setId(ownerId);
543	        pet.setOwner(owner);
544	        pet.getType().setName(null);
545	        this.clinicService.savePet(pet);
546	        PetDto petDto = petMapper.toPetDto(pet);
547	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
548	            .buildAndExpand(pet.getId()).toUri());
549	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
550	    }
