69	     * derived from the postcode at create time. When the customerCode is absent or malformed
70	     * (e.g. legacy records), it falls back to the postcode range and then the fixed city-to-region
71	     * table, returning {@code UNKNOWN} when neither source resolves.
72	     */
73	    default String locality(Owner owner) {
74	        String code = owner.getCustomerCode();
75	        if (code != null) {
76	            int dash = code.indexOf('-');
77	            if (dash > 0) {
78	                return code.substring(0, dash);
79	            }
80	        }
81	        String region = regionFromPostcode(owner);
82	        if (region != null) {
83	            return region;
84	        }
85	        return cityRegion(owner);
