90	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). Returns {@code UNKNOWN}
91	     * when the city is absent or not in the table.
92	     */
93	    default String cityRegion(Owner owner) {
94	        String city = owner.getCity();
95	        if (city == null) {
96	            return "UNKNOWN";
97	        }
98	        switch (city) {
99	            case "Sydney":
100	                return "NSW";
101	            case "Melbourne":
102	                return "VIC";
103	            case "Brisbane":
104	                return "QLD";
105	            default:
106	                return "UNKNOWN";
107	        }
108	    }
109	
110	    /**
111	     * Resolves the region from the owner's 4-digit postcode range, or {@code null}
112	     * when the postcode is absent, malformed, or in no known range.
113	     */
114	    default String regionFromPostcode(Owner owner) {
115	        String postcode = owner.getPostcode();
116	        if (postcode == null) {
117	            return null;
118	        }
119	        int code;
120	        try {
121	            code = Integer.parseInt(postcode.trim());
122	        }
123	        catch (NumberFormatException ex) {
124	            return null;
125	        }
126	        if (code >= 2000 && code <= 2099) {
127	            return "NSW";
128	        }
129	        if (code >= 3000 && code <= 3099) {
